package com.acromere.transaction;

/**
 * Internal wrapper that pairs a {@link TxnEventTarget} with a {@link TxnEvent}
 * to be dispatched. Used internally by the transaction system to collect and
 * distribute events generated by transaction operations.
 *
 * @param target The target to dispatch the event to
 * @param event  The event to dispatch
 */
record TxnEventWrapper(TxnEventTarget target, TxnEvent event) {

	TxnEventWrapper {
		if( target == null ) throw new NullPointerException( "Target cannot be null" );
		if( event == null ) throw new NullPointerException( "Event cannot be null" );
	}

}
